From 1d8bfc72d39b48049c0fb28cdf01f485239e9c97 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:28:04 +0100
Subject: [PATCH] kded: add quiet hours that mute all audio at set times

There was no way to keep the computer silent at night or at work, so it
could make noise on login or wake-up before audio could be muted. Quiet
hours now mute all audio between two times, on login and on wake-up.

BUG: 429663
---
 src/globalconfig.kcfg               | 20 +++++++++
 src/kcm/ui/TimeSpinBox.qml          | 17 ++++++++
 src/kcm/ui/VolumeControlsConfig.qml | 34 +++++++++++++++
 src/kded/audioshortcutsservice.cpp  | 66 ++++++++++++++++++++++++++++-
 src/kded/audioshortcutsservice.h    | 11 ++++-
 5 files changed, 145 insertions(+), 3 deletions(-)
 create mode 100644 src/kcm/ui/TimeSpinBox.qml

diff --git a/src/globalconfig.kcfg b/src/globalconfig.kcfg
index 29dd8626..8f84b4c4 100644
--- a/src/globalconfig.kcfg
+++ b/src/globalconfig.kcfg
@@ -60,5 +60,25 @@
         <entry name="GlobalMuteSourcesMutedDevices" type="StringList">
             <label>Sources that were muted globally, and should be unmuted after global mute is disabled.</label>
         </entry>
+        <entry name="QuietHours" type="Bool">
+            <label>Mute all audio during quiet hours.</label>
+            <default>false</default>
+        </entry>
+        <entry name="QuietHoursStart" type="Int">
+            <label>Start of quiet hours, in minutes after midnight.</label>
+            <default>1320</default>
+            <min>0</min>
+            <max>1439</max>
+        </entry>
+        <entry name="QuietHoursEnd" type="Int">
+            <label>End of quiet hours, in minutes after midnight.</label>
+            <default>420</default>
+            <min>0</min>
+            <max>1439</max>
+        </entry>
+        <entry name="QuietHoursMuted" type="Bool">
+            <label>Global mute was enabled by quiet hours, and should be disabled when they end.</label>
+            <default>false</default>
+        </entry>
     </group>
 </kcfg>
