diff --git a/src/kded/audioshortcutsservice.cpp b/src/kded/audioshortcutsservice.cpp
index b7e42fa2..64d2349f 100644
--- a/src/kded/audioshortcutsservice.cpp
+++ b/src/kded/audioshortcutsservice.cpp
@@ -12,6 +12,7 @@
 #include <QDBusMessage>
 #include <QGuiApplication>
 #include <QStringBuilder>
+#include <QTime>

 #include <KGlobalAccel>
 #include <KLocalizedString>
@@ -48,11 +49,26 @@ AudioShortcutsService::AudioShortcutsService(QObject *parent, const QList<QVaria
                 m_mutedMicrophoneReminder.reset();
             }
         }
+        if (group.name() == "General"_ba && (names.contains("QuietHours"_ba) || names.contains("QuietHoursStart"_ba) || names.contains("QuietHoursEnd"_ba))) {
+            updateQuietHours(false);
+        }
     });
     if (m_globalConfig->mutedMicrophoneReminderOsd()) {
         m_mutedMicrophoneReminder = std::make_unique<MutedMicrophoneReminder>();
     }

+    m_quietHoursTimer.setInterval(std::chrono::minutes(1));
+    connect(&m_quietHoursTimer, &QTimer::timeout, this, [this]() {
+        updateQuietHours(false);
+    });
+    QDBusConnection::systemBus().connect(u"org.freedesktop.login1"_s,
+                                         u"/org/freedesktop/login1"_s,
+                                         u"org.freedesktop.login1.Manager"_s,
+                                         u"PrepareForSleep"_s,
+                                         this,
+                                         SLOT(handlePrepareForSleep(bool)));
+    updateQuietHours(true);
+
     connect(PulseAudioQt::Context::instance()->server(), &PulseAudioQt::Server::defaultSinkChanged, this, &AudioShortcutsService::handleDefaultSinkChange);
     connect(PulseAudioQt::Context::instance(), &PulseAudioQt::Context::stateChanged, this, &AudioShortcutsService::contextConnectedChanged);
     connect(PulseAudioQt::Context::instance(), &PulseAudioQt::Context::autoConnectingChanged, this, &AudioShortcutsService::contextAutoConnectingChanged);
@@ -553,7 +569,7 @@ void AudioShortcutsService::enableGlobalSourceMute()
     showMicMute(0);
 }

-void AudioShortcutsService::disableGlobalSinkMute()
+void AudioShortcutsService::disableGlobalSinkMute(bool feedback)
 {
     QStringList globalMuteMutedDevices = m_globalConfig->globalMuteSinksMutedDevices();
     for (int i = 0; i < m_sinkModel->rowCount(); ++i) {
@@ -562,12 +578,15 @@ void AudioShortcutsService::disableGlobalSinkMute()

     m_globalConfig->setGlobalMuteSinksMutedDevices(globalMuteMutedDevices);
     m_globalConfig->setGlobalMuteSinks(false);
+    m_globalConfig->setQuietHoursMuted(false);
     m_globalConfig->save();

     const auto sink = m_preferredDevice.sink();
     if (sink) {
         showMute(volumePercent(sink->volume()));
-        playFeedback(-1);
+        if (feedback) {
+            playFeedback(-1);
+        }
     }
 }

@@ -605,6 +624,49 @@ void AudioShortcutsService::pushToTalk(bool talk)
     showPushToTalk(talk);
 }

+bool AudioShortcutsService::isQuietHours() const
+{
+    const QTime now = QTime::currentTime();
+    const int minutes = now.hour() * 60 + now.minute();
+    const int start = m_globalConfig->quietHoursStart();
+    const int end = m_globalConfig->quietHoursEnd();
+
+    if (start <= end) {
+        return minutes >= start && minutes < end;
+    }
+    // Quiet hours go past midnight
+    return minutes >= start || minutes < end;
+}
+
+void AudioShortcutsService::updateQuietHours(bool muteAgain)
+{
+    if (m_globalConfig->quietHours()) {
+        m_quietHoursTimer.start();
+    } else {
+        m_quietHoursTimer.stop();
+    }
+
+    const bool quietHours = m_globalConfig->quietHours() && isQuietHours();
+    if (quietHours && (muteAgain || !m_quietHours)) {
+        // Mute when quiet hours begin, and again on login and wake-up, in case audio was unmuted in between
+        if (!m_globalConfig->globalMuteSinks()) {
+            enableGlobalSinkMute();
+            m_globalConfig->setQuietHoursMuted(true);
+            m_globalConfig->save();
+        }
+    } else if (!quietHours && m_globalConfig->quietHoursMuted()) {
+        disableGlobalSinkMute(false);
+    }
+    m_quietHours = quietHours;
+}
+
+void AudioShortcutsService::handlePrepareForSleep(bool sleep)
+{
+    if (!sleep) {
+        updateQuietHours(true);
+    }
+}
+
 bool AudioShortcutsService::contextConnected() const
 {
     return PulseAudioQt::Context::instance()->state() == PulseAudioQt::Context::State::Ready;
